import numpy as np
f=open('xtbopt.xyz').read().splitlines();n=int(f[0]); ats=[]; xyz=[]
for line in f[2:2+n]:
 s=line.split();ats.append(s[0]);xyz.append(list(map(float,s[1:4])))
x=np.array(xyz)
for i,a in enumerate(ats):
 if a in ('Ir','Zn') or (a=='C' and i in range(0,66)):
  print(i,a,np.round(x[i],3))
ir=ats.index('Ir'); zn=ats.index('Zn')
print('IrZn',np.linalg.norm(x[ir]-x[zn]))
for i,a in enumerate(ats):
 if a=='H':
  dIr=np.linalg.norm(x[i]-x[ir]);dZn=np.linalg.norm(x[i]-x[zn])
  if dIr<2.5 or dZn<2.5:print(i,'H distances Ir Zn',round(dIr,2),round(dZn,2))
PY
